import type { FeedbackPayload, OcrRequest, OcrResult } from '@/types';

export interface OcrApi {
  recognize(request: OcrRequest): Promise<OcrResult>;
  translate(text: string, signal?: AbortSignal): Promise<string>;
  sendFeedback(payload: FeedbackPayload): Promise<void>;
  /** Searchable PDF generated by the backend. */
  exportPdf(input: { title: string; text: string }): Promise<Blob>;
  health(): Promise<boolean>;
  /** Kannada speech for one sentence (audio/wav), generated by the backend. */
  speak(text: string, signal?: AbortSignal): Promise<Blob>;
}
